<template>
  <article class="music-detail-card">
    <header id="sec-chart-info" class="top-info">
      <p class="music-chapter">{{ dict.chapter || '-' }}</p>
      <h2 class="music-name">{{ dict.name || '-' }}</h2>
      <p class="music-composer">{{ dict.composer || '-' }}</p>
    </header>

    <!-- 换过曲绘的曲目：主曲绘两侧放箭头，左边翻更早的图，右边翻之后的差分图 -->
    <div class="illustration-stage" :class="{ 'illustration-stage--switchable': variantList.length > 1 }">
      <button
        v-if="variantList.length > 1"
        type="button"
        class="art-arrow art-arrow--left"
        :disabled="!canStepVariant(-1)"
        aria-label="看更早的曲绘"
        @click="stepVariant(-1)"
      >
        <i class="mdi mdi-chevron-left"></i>
      </button>

      <figure class="image-container">
        <img
          :src="illustrationSrc"
          :alt="dict.name || '曲绘'"
          class="illustration-image"
        />
      </figure>

      <button
        v-if="variantList.length > 1"
        type="button"
        class="art-arrow art-arrow--right"
        :disabled="!canStepVariant(1)"
        aria-label="看之后的曲绘"
        @click="stepVariant(1)"
      >
        <i class="mdi mdi-chevron-right"></i>
      </button>

      <!-- 与曲绘等宽的两栏署名：画师名义是曲绘上的署名，画师是本人 -->
      <dl class="illustration-credits">
        <div class="credit-item">
          <dt class="credit-label">画师名义</dt>
          <dd class="credit-value" :title="currentCredits.nominal">{{ currentCredits.nominal || '-' }}</dd>
        </div>
        <div class="credit-item">
          <dt class="credit-label">画师</dt>
          <dd class="credit-value" :title="currentCredits.artist">{{ currentCredits.artist || '-' }}</dd>
        </div>
      </dl>
    </div>

    <!-- 侧栏「谱面数据」这一组的锚点落在这里（组 = 基本信息 + 难度与物量） -->
    <div id="grp-chart-data" class="chart-data">
      <dl id="sec-basic" class="info-grid">
        <div v-for="(field, index) in otherFields" :key="index" class="info-item">
          <dt class="info-label">{{ field.label }}</dt>
          <dd class="info-value">{{ dict[field.key] || '-' }}</dd>
        </div>
      </dl>

      <section id="sec-difficulty" class="difficulty-section">
        <div class="table-wrapper">
          <table class="dt-table difficulty-table">
            <thead>
              <tr>
                <th>难度</th>
                <th>定数</th>
                <th>物量</th>
                <th>谱师名义</th>
                <th>谱师</th>
                <th class="num">Tap</th>
                <th class="num">Drag</th>
                <th class="num">Hold</th>
                <th class="num">Flick</th>
                <th class="num">判定线</th>
                <th v-if="hasNoise" class="num" title="噪域数量">噪域</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="(item, index) in validDifficultyData"
                :key="index"
              >
                <td>
                  <span class="dt-diff" :class="`dt-diff--${item.diffName.toLowerCase()}`">{{ item.diffName }}</span>
                </td>
                <td class="num strong">{{ item.data.lvl || '-' }}</td>
                <td class="num">{{ item.data.notecount || '-' }}</td>
                <td>{{ item.data.charter || '-' }}</td>
                <td>{{ item.data.tcharter || '-' }}</td>
                <td class="num">{{ item.data.tap ?? '-' }}</td>
                <td class="num">{{ item.data.drag ?? '-' }}</td>
                <td class="num">{{ item.data.hold ?? '-' }}</td>
                <td class="num">{{ item.data.flick ?? '-' }}</td>
                <td class="num">{{ item.data.line ?? '-' }}</td>
                <td v-if="hasNoise" class="num">{{ noiseText(item.data.noise) }}</td>
              </tr>
            </tbody>
          </table>
        </div>
        <p v-if="!validDifficultyData.length" class="dt-empty">该曲目暂无谱面数据</p>
      </section>
    </div>
  </article>
</template>

<script setup>
import { defineProps, ref, computed, onMounted, onUnmounted, watch } from 'vue'
import { useRemScale } from '../../utils/rem.js'
import { illPath } from '../../api/common.js'
import { loadIllVariants } from '../../api/illVariants.js'
import { compareVersion } from '../../api/levelHistory.js'

import { setAnchorNav, clearAnchorNav } from '../../composables/useAnchorNav.js'

useRemScale()

// 详情页的分区（渲染成侧栏二级目录，点它滚到对应锚点）
const ANCHOR_NAV = [
  { id: 'sec-chart-info', label: '曲目信息', icon: 'music-circle-outline' },
  {
    id: 'grp-chart-data',
    label: '谱面数据',
    icon: 'table-large',
    children: [
      { id: 'sec-basic', label: '基本信息', icon: 'information-outline' },
      { id: 'sec-difficulty', label: '难度与物量', icon: 'chart-bar' }
    ]
  }
]

const otherFields = [
  { label: '更新', key: 'date' },
  { label: '版本', key: 'version' },
  { label: 'BPM', key: 'BPM' },
  { label: '时长', key: 'duration' },
  { label: '关联', key: 'relation' },
  { label: '赛事', key: 'competition'}
];

const difficultyKeys = ['EZ', 'HD', 'IN', 'AT', 'LY', 'SP'];

const props = defineProps({
  dict: {
    type: Object,
    required: true,
    default: () => ({})
  },
  // 曲目键名（曲绘变体表按它索引）
  songKey: {
    type: String,
    default: ''
  }
})

const imagePath = ref('')
const isImageError = ref(false)

onMounted(() => {
  initImage()
  setAnchorNav(ANCHOR_NAV)
})

onUnmounted(() => {
  clearAnchorNav()
})

const getIllAssetsPath = computed(() => {
  if (props.dict?.illAssets && typeof props.dict.illAssets === 'string') {
    return props.dict.illAssets
  }
  return ''
})

const difficultyTypes = computed(() => {
  const result = {};
  difficultyKeys.forEach(key => {
    result[key] = props.dict[key] || {};
  });
  return result;
});

const validDifficultyData = computed(() => {
  const validData = [];
  for (const diffName of difficultyKeys) {
    const diffData = difficultyTypes.value[diffName] || {};
    if (!isDiffEmpty(diffData)) {
      validData.push({
        diffName,
        data: diffData
      });
    }
  }
  return validData;
});

const isDiffEmpty = (diffData) => {
  return !diffData.tcharter && !diffData.dif && !diffData.lvl && !diffData.notecount;
}

// 噪域数量只有部分谱面有（infos.json 里是该档的 noise 字段），整首都查不到就不出这一列
const hasNoise = computed(() => {
  return validDifficultyData.value.some(({ data }) => data.noise != null && data.noise !== '')
})

// 有噪域列的曲目里，没记录的难度补一个 -；0 是有效值，不能当成空
const noiseText = (value) => (value === '' || value == null ? '-' : value)

const initImage = () => {
  imagePath.value = getIllAssetsPath.value
  isImageError.value = false
}

// 曲绘变体（files/infos/illvariants.json）：0 现用曲绘，负数是被换下的旧图，正数是差分图
const illVariantMap = ref(null)

const variantList = computed(() => {
  const entry = illVariantMap.value?.songs?.[props.songKey]
  if (!entry || !entry.variants) return []
  const variants = Object.keys(entry.variants).map(Number)
  // 从左到右：旧图 → 现用曲绘(0) → 差分图(1、2、3)。旧图不按变体号排，
  // 而按「被换下的版本」排：先被换下的更早、放得更靠左，所以 0 往左第一下是最后换下的那张
  const replacedAt = (variant) => entry.variants[String(variant)]?.replacedAt || ''
  variants.sort((a, b) => {
    if (a === 0) return b < 0 ? 1 : -1
    if (b === 0) return a < 0 ? -1 : 1
    if (a < 0 && b < 0) {
      const byVersion = compareVersion(replacedAt(a), replacedAt(b))
      return byVersion || a - b
    }
    if (a < 0) return -1
    if (b < 0) return 1
    return a - b
  })
  return variants.map((variant) => ({
    variant,
    src: illPath(props.songKey, variant)
  }))
})

// 当前显示哪一版曲绘：默认停在现用曲绘（0），用主图两侧的箭头在旧图与差分图之间翻
const selectedVariant = ref(null)

const variantIndex = computed(() => {
  const index = variantList.value.findIndex((item) => item.variant === selectedVariant.value)
  return index === -1 ? 0 : index
})

const currentVariant = computed(() => variantList.value[variantIndex.value] || null)

// 主图沿用 infos 给的高清图；翻到别的变体时换成那一版的高清图
const illustrationSrc = computed(() => currentVariant.value?.src || imagePath.value)

// 图下两栏署名跟着选中项走：现用曲绘取 infos.json，旧图 / 差分图取曲绘变体表
const currentCredits = computed(() => {
  const entry = illVariantMap.value?.songs?.[props.songKey]
  const variant = currentVariant.value?.variant
  const info = variant != null ? entry?.variants?.[String(variant)] : null
  return {
    nominal: info?.nominal || props.dict.illustrator || '',
    artist: info?.artist || props.dict.illustratorArtist || ''
  }
})

// 没有更早 / 更晚的曲绘时箭头置灰，别让人以为点了没反应
const canStepVariant = (step) => {
  const next = variantIndex.value + step
  return next >= 0 && next < variantList.value.length
}

const stepVariant = (step) => {
  const item = variantList.value[variantIndex.value + step]
  if (item) selectedVariant.value = item.variant
}

// 数据到了把选中项归位到现用曲绘
watch(variantList, (list) => {
  selectedVariant.value = list.some((item) => item.variant === 0) ? 0 : (list[0]?.variant ?? null)
})

onMounted(() => {
  if (props.songKey) {
    loadIllVariants()
      .then((data) => {
        illVariantMap.value = data
      })
      .catch(() => {
        // 没有这张表就当这首歌只有一张曲绘，不影响详情页其它内容
        illVariantMap.value = null
      })
  }
})
</script>

